penalty); items stay on the corpse for you to retrieve.$help$,
  min_level = 0,
  category = 'guide',
  usage = NULL,
  source_file = 'data/help/death.md',
  updated_at = now()
WHERE id = (
  SELECT h.id FROM "HelpEntry" h
